import{_ as a,a as o}from"./chunks/demo_02.CQmw40B0.js";import{_ as i,Y as n,o as s,c as r,aq as l,H as p}from"./chunks/framework.d4q-Q6bs.js";import"./chunks/theme.x-68MGni.js";const k=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/home.md","filePath":"en/guide/home.md"}'),c={name:"en/guide/home.md"};function h(u,e,d,m,f,g){const t=n("NolebaseGitChangelog");return s(),r("div",null,[e[0]||(e[0]=l('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><blockquote><p><code>PanguText</code> is a solution for CJK (Chinese, Japanese, Korean) and English word, half-width number spacing.</p></blockquote><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>This project was created because, until now, there hasn’t been a public solution to perfectly address the typography issues between Chinese, Japanese, Korean, and English. Typically, when mixing CJK (i.e. Chinese, Japanese, Korean) with English, aesthetic issues can arise—a historical legacy stemming from the differences in writing conventions between full-width and half-width characters. Although the W3C has now established CJK typography guidelines, only a few individuals or companies willing to adhere to these standards have adopted this approach.</p><p>Currently, the known vendor solutions are as follows:</p><ul><li>Apple platforms (iOS, iPadOS, macOS, tvOS, watchOS) text typography solutions</li><li>Xiaomi’s (HyperOS) text typography optimization</li><li>OrginOS’s font-based text typography optimization</li></ul><p>However, these solutions are closed-source and cannot be implemented on other platforms. We aim to provide an open-source solution adaptable to various scenarios, featuring low intrusiveness and easy integration, allowing more developers to effectively address text typography issues.</p><p>The primary inspiration for this project comes from <a href="https://github.com/vinta/pangu.js" target="_blank" rel="noreferrer">pangu.js</a>, which offers a set of regular expressions for CJK typography. We have optimized these solutions to format text across platforms without inserting extra space characters. We extend this approach further to explore additional possibilities.</p><p>Heartfelt thanks to the original developer of <strong>pangu.js</strong> for providing the foundational solution.</p><h2 id="effects" tabindex="-1">Effects <a class="header-anchor" href="#effects" aria-label="Permalink to &quot;Effects&quot;">​</a></h2><p>As you can see, the typography scheme of PanguText does not work by simply inserting spaces between CJK characters and English words. Instead, it leverages each platform&#39;s native handling to automatically add whitespace between these characters, ensuring minimal intrusion.</p><blockquote><p>Before Applying (Top) vs. After Applying (Bottom)</p></blockquote><img src="'+a+'" width="300"><blockquote><p>Dynamic Application</p></blockquote><img src="'+o+'" width="480"><p>PanguText supports dynamic application, which means it can add whitespace gaps to each character on-the-fly as you input text.</p><div class="tip custom-block"><p class="custom-block-title">Developer&#39;s Perspective</p><p>I personally do not recommend manually inserting spaces between CJK and English characters for typographic refinement if your software or system natively supports enhanced typographic formatting.</p><p>The spacing can vary across fonts, which may lead to formatting issues and the insertion of undesired space characters.</p><p>In certain contexts, such as URLs, filenames, or hashtags containing “#”, these spaces are not acceptable.</p><p>However, in special scenarios—for example, within code comments or documentation—it can be beneficial to add spaces, as these areas typically do not employ automated formatting tools.</p><p>Another point to consider is the use of different punctuation marks in different languages. Avoid mixing full-width and half-width punctuation marks. If you must use half-width punctuation marks to annotate full-width text, ensure that the half-width marks are followed by a space to complete the character space (the same applies to English).</p></div><h2 id="language-requirement" tabindex="-1">Language Requirement <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;Language Requirement&quot;">​</a></h2><p>It is recommended to use Kotlin as the preferred development language.</p><p>This project is entirely written in Kotlin and is compatible with Java in some parts, but it may not be fully compatible.</p><p>All demo &amp; sample codes in the document will be described using Kotlin, if you don’t know how to use Kotlin at all, you may not get the best experience.</p><h2 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h2><p>The maintenance of this project is inseparable from the support and contributions of all developers.</p><p>This project is currently in its early stages, and there may still be some problems or lack of functions you need.</p><p>If possible, feel free to submit a PR to contribute features you think are needed to this project or go to <a href="https://github.com/BetterAndroid/PanguText/issues" target="_blank" rel="noreferrer">GitHub Issues</a> to make suggestions to us.</p>',25)),p(t)])}const v=i(c,[["render",h]]);export{k as __pageData,v as default};
